   * output ports.  Use named arguments to check subsets of the output ports.
   * @param threatReport method that will be called with the value of the outgoing data
   *        port 'threatReport'.
   */
  def check_concrete_output(threatReport: Frigate_Threat_Egress_Supervisor.ThreatReport.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val threatReportValue: Frigate_Threat_Egress_Supervisor.ThreatReport.Type = get_threatReport().get
